CREATE TYPE "Gender" AS ENUM ('MALE', 'FEMALE');
CREATE TYPE "EmployeeInternalStatus" AS ENUM ('GTY', 'CGTY', 'GTTY', 'TENDIK', 'TENAGA_PESANTREN');
CREATE TYPE "EmploymentRelationship" AS ENUM ('PERMANENT', 'FIXED_TERM', 'PART_TIME', 'FREELANCE', 'OTHER');
CREATE TYPE "DocumentType" AS ENUM ('APPOINTMENT_DECREE', 'CONTRACT', 'DIPLOMA', 'CERTIFICATE', 'ASSIGNMENT');

CREATE TABLE "organizations" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "organizations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "units" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"type" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "units_pkey" PRIMARY KEY ("id"));
CREATE TABLE "employees" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_number" TEXT NOT NULL,"full_name" TEXT NOT NULL,"gender" "Gender" NOT NULL,"birth_date" DATE,"email" TEXT,"phone" TEXT,"address" TEXT,"last_education" TEXT,"competencies" TEXT,"start_date" DATE NOT NULL,"internal_status" "EmployeeInternalStatus" NOT NULL,"primary_unit_id" UUID NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"archived_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "employees_pkey" PRIMARY KEY ("id"));
CREATE TABLE "employment_contracts" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_id" UUID NOT NULL,"relationship_type" "EmploymentRelationship" NOT NULL,"start_date" DATE NOT NULL,"end_date" DATE,"notes" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "employment_contracts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "positions" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "positions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "employee_assignments" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_id" UUID NOT NULL,"unit_id" UUID NOT NULL,"position_id" UUID NOT NULL,"is_primary" BOOLEAN NOT NULL DEFAULT false,"effective_from" DATE NOT NULL,"effective_to" DATE,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "employee_assignments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "employee_documents" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_id" UUID NOT NULL,"type" "DocumentType" NOT NULL,"title" TEXT NOT NULL,"storage_key" TEXT NOT NULL,"original_name" TEXT NOT NULL,"mime_type" TEXT NOT NULL,"size_bytes" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "employee_documents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_id" UUID,"email" TEXT NOT NULL,"name" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"mfa_enabled" BOOLEAN NOT NULL DEFAULT false,"failed_login_attempts" INTEGER NOT NULL DEFAULT 0,"locked_until" TIMESTAMP(3),"password_reset_hash" TEXT,"password_reset_expiry" TIMESTAMP(3),"session_version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "roles" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"is_system" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "roles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "permissions" ("id" UUID NOT NULL,"key" TEXT NOT NULL,"description" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "permissions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL,"role_id" UUID NOT NULL,"assigned_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "user_roles_pkey" PRIMARY KEY ("user_id","role_id"));
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL,"permission_id" UUID NOT NULL,CONSTRAINT "role_permissions_pkey" PRIMARY KEY ("role_id","permission_id"));
CREATE TABLE "audit_logs" ("id" UUID NOT NULL,"organization_id" UUID,"actor_id" UUID,"action" TEXT NOT NULL,"entity_type" TEXT NOT NULL,"entity_id" TEXT,"metadata" JSONB,"ip_address" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id"));

